}

/**
 * Structure that store Atom Entry Properties
 *
 * @package AtomLib
 */
#[\AllowDynamicProperties]
class AtomEntry {
	/**
	 * Stores Links
	 * @var array
	 * @access public
	 */
    public $links = [];
    /**
     * Stores Categories
     * @var array
	 * @access public
     */
    public $categories = [];
}

/**
 * AtomLib Atom Parser API
 *
 * @package AtomLib
 */
#[\AllowDynamicProperties]
class AtomParser {

    public $NS = 'http://www.w3.org/2005/Atom';
    public $ATOM_CONTENT_ELEMENTS = ['content','summary','title','subtitle','rights'];
    public $ATOM_SIMPLE_ELEMENTS = ['id','updated','published','draft'];

    public $debug = false;

    public $depth = 0;
    public $indent = 2;
    public $in_content;
    public $ns_contexts = [];
    public $ns_decls = [];
    public $content_ns_decls = [];
    public $content_ns_contexts = [];
    public $is_xhtml = false;
    public $is_html = false;
    public $is_text = true;
    public $skipped_div = false;

    public $FILE = "php://input";

    public $feed;
    public $current;

    public $map_attrs_func;
    public $map_xmlns_func;
    public $error;
    public $content;

    public function __construct() {

        $this->feed = new AtomFeed();
        $this->current = null;
        $this->map_attrs_func = static fn($k, $v) => "$k=\"$v\"";
        $this->map_xmlns_func = static function ($p, $n) {
            $xd = "xmlns";
            if (strlen((string) $n[0]) > 0) {
                $xd .= ":{$n[0]}";
            }
            return "{$xd}=\"{$n[1]}\"";
        };
    }

    /**
     * PHP4-style constructor, kept for backward compatibility.
     */
    public function AtomParser() {
        self::__construct();
    }

    function _p($msg) {
        if($this->debug) {
            print str_repeat(" ", $this->depth * $this->indent) . $msg ."\n";
        }
    }

    function error_handler($log_level, $log_text, $error_file, $error_line) {
        $this->error = $log_text;
    }

    function parse() {

        set_error_handler($this->error_handler(...));

        array_unshift($this->ns_contexts, []);

        $parser = xml_parser_create_ns();
        xml_set_element_handler($parser, $this->start_element(...), $this->end_element(...));
        xml_parser_set_option($parser,XML_OPTION_CASE_FOLDING,0);
        xml_parser_set_option($parser,XML_OPTION_SKIP_WHITE,0);
        xml_set_character_data_handler($parser, $this->cdata(...));
        xml_set_default_handler($parser, $this->_default(...));
        xml_set_start_namespace_decl_handler($parser, $this->start_ns(...));
        xml_set_end_namespace_decl_handler($parser, $this->end_ns(...));

        $this->content = '';

        $ret = true;

        $fp = fopen($this->FILE, "r");
        if ($fp !== false) {
            while ($data = fread($fp, 4096)) {
                if($this->debug) $this->content .= $data;

                if(!xml_parse($parser, $data, feof($fp))) {
                    trigger_error(sprintf(__('XML error: %s at line %d')."\n",
                        xml_error_string(xml_get_error_code($parser)),
                        xml_get_current_line_number($parser)));
                    $ret = false;
                    break;
                }
            }
            fclose($fp);
        }

        xml_parser_free($parser);

        restore_error_handler();

        return $ret;
    }

    function start_element($parser, $name, $attrs) {

        $name_parts = explode(":", $name);
        $tag = array_pop($name_parts);

        switch($name) {
            case $this->NS . ':feed':
                $this->current = $this->feed;
                break;
            case $this->NS . ':entry':
                $this->current = new AtomEntry();
                break;
        };

        $this->_p("start_element('$name')");
        #$this->_p(print_r($this->ns_contexts,true));
        #$this->_p('current(' . $this->current . ')');

        array_unshift($this->ns_contexts, $this->ns_decls);

        $this->depth++;

        if(!empty($this->in_content)) {

            $this->content_ns_decls = [];

            if($this->is_html || $this->is_text)
                trigger_error("Invalid content in element found. Content must not be of type text or html if it contains markup.");

            $attrs_prefix = [];

            // resolve prefixes for attributes
            foreach($attrs as $key => $value) {
                $with_prefix = $this->ns_to_prefix($key, true);
                $attrs_prefix[$with_prefix[1]] = $this->xml_escape($value);
            }

            $attrs_str = implode(' ', array_map($this->map_attrs_func, array_keys($attrs_prefix), array_values($attrs_prefix)));
            if(strlen($attrs_str) > 0) {
                $attrs_str = " " . $attrs_str;
            }

            $with_prefix = $this->ns_to_prefix($name);

            if(!$this->is_declared_content_ns($with_prefix[0] ?? null)) {
                $this->content_ns_decls[] = $with_prefix[0] ?? null;
            }

            $xmlns_str = '';
            if(count($this->content_ns_decls) > 0) {
                array_unshift($this->content_ns_contexts, $this->content_ns_decls);
                $xmlns_str .= implode(' ', array_map($this->map_xmlns_func, array_keys($this->content_ns_contexts[0]), array_values($this->content_ns_contexts[0])));
                if(strlen($xmlns_str) > 0) {
                    $xmlns_str = " " . $xmlns_str;
                }
            }

            $this->in_content[] = [$tag, $this->depth, "<". ($with_prefix[1] ?? null) ."{$xmlns_str}{$attrs_str}" . ">"];

        } else if(in_array($tag, $this->ATOM_CONTENT_ELEMENTS) || in_array($tag, $this->ATOM_SIMPLE_ELEMENTS)) {
            $this->in_content = [];
            $attr_type = $attrs['type'] ?? null;
            $this->is_xhtml = $attr_type == 'xhtml';
            $this->is_html = $attr_type == 'html' || $attr_type == 'text/html';
            $this->is_text = !in_array('type',array_keys($attrs)) || $attr_type == 'text';
            $type = $this->is_xhtml ? 'XHTML' : ($this->is_html ? 'HTML' : ($this->is_text ? 'TEXT' : $attr_type));

            if(in_array('src',array_keys($attrs))) {
                $this->current->$tag = $attrs;
            } else {
                $this->in_content[] = [$tag,$this->depth, $type];
            }
        } else if($tag == 'link') {
            $this->current->links[] = $attrs;
        } else if($tag == 'category') {
            $this->current->categories[] = $attrs;
        }

        $this->ns_decls = [];
    }

    function end_element($parser, $name) {

        $name_parts = explode(":", $name);
        $tag = array_pop($name_parts);

        $ccount = is_countable($this->in_content) ? count($this->in_content) : 0;

        # if we are *in* content, then let's proceed to serialize it
        if(!empty($this->in_content)) {
            # if we are ending the original content element
            # then let's finalize the content
            if($this->in_content[0][0] == $tag &&
                $this->in_content[0][1] == $this->depth) {
                $origtype = $this->in_content[0][2];
                array_shift($this->in_content);
                $newcontent = [];
                foreach($this->in_content as $c) {
                    if(is_array($c) && count($c) == 3) {
                        $newcontent[] = $c[2];
                    } else {
                        if($this->is_xhtml || $this->is_text) {
                            $newcontent[] = $this->xml_escape($c);
                        } else {
                            $newcontent[] = $c;
                        }
                    }
                }
                if(in_array($tag, $this->ATOM_CONTENT_ELEMENTS)) {
                    $this->current->$tag = [$origtype, implode('',$newcontent)];
                } else {
                    $this->current->$tag = implode('',$newcontent);
                }
                $this->in_content = [];
            } else if(is_array($this->in_content[$ccount-1]) &&
                $this->in_content[$ccount-1][0] == $tag &&
                $this->in_content[$ccount-1][1] == $this->depth) {
                $this->in_content[$ccount-1][2] = substr($this->in_content[$ccount-1][2],0,-1) . "/>";
            } else {
                # else, just finalize the current element's content
                $endtag = $this->ns_to_prefix($name);
                $this->in_content[] = [$tag, $this->depth, "</" . ($endtag[1] ?? null) . ">"];
            }
        }

        array_shift($this->ns_contexts);

        $this->depth--;

        if($name == ($this->NS . ':entry')) {
            $this->feed->entries[] = $this->current;
            $this->current = null;
        }

        $this->_p("end_element('$name')");
    }

    function start_ns($parser, $prefix, $uri) {
        $this->_p("starting: " . $prefix . ":" . $uri);
        $this->ns_decls[] = [$prefix,$uri];
    }

    function end_ns($parser, $prefix) {
        $this->_p("ending: #" . $prefix . "#");
    }

    function cdata($parser, $data) {
        $this->_p("data: #" . str_replace(["\n"], ["\\n"], trim($data)) . "#");
        if(!empty($this->in_content)) {
            $this->in_content[] = $data;
        }
    }

    function _default($parser, $data) {
        # when does this gets called?
    }


    function ns_to_prefix($qname, $attr=false) {
        # split 'http://www.w3.org/1999/xhtml:div' into ('http','//www.w3.org/1999/xhtml','div')
        $components = explode(":", $qname);

        # grab the last one (e.g 'div')
        $name = array_pop($components);

        if(!empty($components)) {
            # re-join back the namespace component
            $ns = implode(":",$components);
            foreach($this->ns_contexts as $context) {
                foreach($context as $mapping) {
                    if($mapping[1] == $ns && strlen((string) $mapping[0]) > 0) {
                        return [$mapping, "$mapping[0]:$name"];
                    }
                }
            }
        }

        if($attr) {
            return [null, $name];
        } else {
            foreach($this->ns_contexts as $context) {
                foreach($context as $mapping) {
                    if(strlen((string) $mapping[0]) == 0) {
                        return [$mapping, $name];
                    }
                }
            }
        }
    }

    function is_declared_content_ns($new_mapping) {
        foreach($this->content_ns_contexts as $context) {
            foreach($context as $mapping) {
                if($new_mapping == $mapping) {
                    return true;
                }
            }
        }
        return false;
    }

    function xml_escape($string)
    {
             return str_replace(['&','"',"'",'<','>'],
                ['&amp;','&quot;','&apos;','&lt;','&gt;'],
                $string );
    }
}
'''
open(p,'w').write(head+new)
